-- [SOURCE_QUALIFIER] Step: apply_No_of_Transactions_HOS1
SELECT crt.HOS_CRT_TYPE_CODE as HOS_CRT_TYPE_CODE, crt.HOS_CRT_CODE as HOS_CRT_CODE, COUNT(1) as CNT
FROM SOR_EMS_HOS_CRT crt, SOR_EMS_HOS_CRT_STS crt_sts,
SOR_EMS_HOS_BLK blk, SOR_EMS_HOS_BLK_STS blk_sts,
SOR_EMS_HOS_UNIT unit, SOR_EMS_HOS_UNIT_STS unit_sts,
SOR_EMS_HOW_HOS_OWN how, SOR_EMS_HOW_HOS_OWN_STS how_sts
WHERE crt.HOS_CRT_KEY = crt_sts.HOS_CRT_KEY
AND blk.HOS_BLK_KEY = blk_sts.HOS_BLK_KEY
AND unit.HOS_UNIT_KEY = unit_sts.HOS_UNIT_KEY
AND how.HOS_OWN_KEY = how_sts.HOS_OWN_KEY
AND crt.HOS_CRT_KEY = blk.HOS_CRT_KEY
AND blk.HOS_BLK_KEY = unit.HOS_BLK_KEY
AND unit.HOS_UNIT_KEY = how_sts.HOS_UNIT_KEY
AND crt.HOS_CRT_TYPE_CODE IN ('H','P','M')
AND unit_sts.HOS_UNIT_STS_CODE = 'S'
AND (blk_sts.HOS_BLK_SCHM_OPT_CODE IS NULL OR blk_sts.HOS_BLK_SCHM_OPT_CODE <> 'B')
AND (SUBSTR(blk_sts.FRST_SALE_HOS_PHASE_CODE, 1, 1) BETWEEN '0' AND '9' OR SUBSTR(blk_sts.FRST_SALE_HOS_PHASE_CODE, 1, 1) = ' ')
AND how_sts.HOS_EXOWNR_REF_CODE IS NULL
AND how_sts.HOS_OWN_PCHS_FROM_CODE NOT IN ('OM', 'PP')
AND blk_sts.HOS_BLK_CMPLT_DATE <= ADD_MONTHS(LAST_DAY(TO_DATE('$$v_rpt_mth', 'YYYYMM')), -24)
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN crt_sts.BGN_DATE AND crt_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN how_sts.BGN_DATE AND how_sts.END_DATE
GROUP BY crt.HOS_CRT_TYPE_CODE, crt.HOS_CRT_CODE;

-- [SOURCE_QUALIFIER] Step: apply_No_of_Transactions_TPS1
SELECT est.EST_TYPE_CODE AS EST_TYPE_CODE, est.EST_CODE AS EST_CODE, SUBSTR(unit.UNIT_ADDR_CODE, 1, 14) AS UNIT_ADDR_CODE
FROM SOR_HSM_EST est,
SOR_HSM_EST tps_est, SOR_EMS_HSM_TPS_EST_STS tps_est_sts,
SOR_HSM_BLK blk, SOR_HSM_BLK_STS blk_sts,
SOR_HSM_UNIT unit, SOR_HSM_UNIT_STS unit_sts,
SOR_EMS_TOW_TPS_AGRMT agrmt, SOR_EMS_TOW_TPS_AGRMT_STS agrmt_sts
WHERE tps_est.EST_KEY = tps_est_sts.EST_KEY
AND blk.BLK_KEY = blk_sts.BLK_KEY
AND unit.UNIT_KEY = unit_sts.UNIT_KEY
AND agrmt.TPS_AGRMT_KEY = agrmt_sts.TPS_AGRMT_KEY
AND est.EST_KEY = tps_est.EST_KEY
AND est.EST_KEY = blk.EST_KEY
AND blk.BLK_KEY = unit.BLK_KEY
AND unit.UNIT_KEY = agrmt_sts.UNIT_KEY
AND tps_est_sts.EST_PHASE_CODE IS NOT NULL 
AND agrmt_sts.TPS_PCHS_FORM_CODE = 'H1'
AND agrmt_sts.TPS_AGRMT_FRST_ASGN_DATE <= ADD_MONTHS(LAST_DAY(TO_DATE('$$v_rpt_mth', 'YYYYMM')), -24)
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN  tps_est_sts.BGN_DATE AND  tps_est_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN agrmt_sts.BGN_DATE AND agrmt_sts.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_No_of_Transactions_TPS
SELECT SUBSTR(cas_sts.UNIT_CODE_ADDR,1,1) AS CRT_TYPE_CODE,
TRIM(SUBSTR(cas_sts.UNIT_CODE_ADDR,2,4)) AS CRT_CODE, COUNT(1)
FROM SOR_EMS_SMS_LN LN, SOR_EMS_SMS_LN_STS ln_sts,
SOR_EMS_SMS_LN_APLY aply, SOR_EMS_SMS_LN_APLY_STS aply_sts,
SOR_EMS_SMS_CAS_CERT cert, SOR_EMS_SMS_CAS_CERT_STS cert_sts,
SOR_EMS_SMS_CAS_APLY cas, SOR_EMS_SMS_CAS_APLY_STS cas_sts  
WHERE LN.LN_KEY = ln_sts.LN_KEY
AND aply.LN_APLY_KEY = aply_sts.LN_APLY_KEY
AND cert.CAS_CERT_KEY = cert_sts.CAS_CERT_KEY
AND cas.CAS_APLY_KEY = cas_sts.CAS_APLY_KEY
AND ln_sts.LN_APLY_KEY = aply.LN_APLY_KEY
AND aply_sts.CAS_CERT_KEY = cert.CAS_CERT_KEY
AND cas_sts.CAS_APLY_KEY = cert_sts.CAS_APLY_KEY
AND ln_sts.LN_STS_CODE IN ('V','S')
AND TRUNC(ln_sts.LN_ISS_DATE,'MM') = TO_DATE('$$v_rpt_mth','yyyymm')
AND ln_sts.SCHM_CODE  = 'T'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN ln_sts.BGN_DATE AND ln_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN aply_sts.BGN_DATE AND aply_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cert_sts.BGN_DATE AND cert_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cas_sts.BGN_DATE AND cas_sts.END_DATE
GROUP BY SUBSTR(cas_sts.UNIT_CODE_ADDR,1,1),
TRIM(SUBSTR(cas_sts.UNIT_CODE_ADDR,2,4));

-- [SOURCE_QUALIFIER] Step: apply_No_of_Transactions_HOS
SELECT SUBSTR(cas_sts.UNIT_CODE_ADDR,1,1) AS TYPE,
TRIM(SUBSTR(cas_sts.UNIT_CODE_ADDR,2,4)) AS CRT_CODE, COUNT(1)
FROM SOR_EMS_SMS_LN LN, SOR_EMS_SMS_LN_STS ln_sts,
SOR_EMS_SMS_LN_APLY aply, SOR_EMS_SMS_LN_APLY_STS aply_sts,
SOR_EMS_SMS_CAS_CERT cert, SOR_EMS_SMS_CAS_CERT_STS cert_sts,
SOR_EMS_SMS_CAS_APLY cas, SOR_EMS_SMS_CAS_APLY_STS cas_sts  
WHERE LN.LN_KEY = ln_sts.LN_KEY
AND aply.LN_APLY_KEY = aply_sts.LN_APLY_KEY
AND cert.CAS_CERT_KEY = cert_sts.CAS_CERT_KEY
AND cas.CAS_APLY_KEY = cas_sts.CAS_APLY_KEY
AND ln_sts.LN_APLY_KEY = aply.LN_APLY_KEY
AND aply_sts.CAS_CERT_KEY = cert.CAS_CERT_KEY
AND cas_sts.CAS_APLY_KEY = cert_sts.CAS_APLY_KEY
AND ln_sts.LN_STS_CODE IN ('V','S')
AND TRUNC(ln_sts.LN_ISS_DATE,'MM') = TO_DATE('$$v_rpt_mth','yyyymm')
AND ln_sts.SCHM_CODE IS NULL
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN ln_sts.BGN_DATE AND ln_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN aply_sts.BGN_DATE AND aply_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cert_sts.BGN_DATE AND cert_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cas_sts.BGN_DATE AND cas_sts.END_DATE
GROUP BY SUBSTR(cas_sts.UNIT_CODE_ADDR,1,1),
TRIM(SUBSTR(cas_sts.UNIT_CODE_ADDR,2,4));

