-- [SOURCE_QUALIFIER] Step: apply_SQ_DPA_FACT_EMS_SMS_DSTR_TXN3
select GNRL_STAT_DMNS_KEY, concat(concat('5',decode(substr($$v_rpt_mth,5,2),'01',substr($$v_rpt_mth,1,4) - 1, '02', substr($$v_rpt_mth,1,4) - 1,'03', substr($$v_rpt_mth,1,4) - 1, substr($$v_rpt_mth,1,4))),'0000') as TIME_DMNS_KEY, DSTR_DMNS_KEY, CRT_DMNS_KEY, SUM(TXN_CNT)
from
(SELECT 
GNRL_STAT_DMNS_KEY, DSTR_DMNS_KEY, CRT_DMNS_KEY, TXN_CNT
FROM DPA_FACT_EMS_SMS_DSTR_TXN
union all
SELECT 
GNRL_STAT_DMNS_KEY, DSTR_DMNS_KEY, CRT_DMNS_KEY, TXN_CNT
FROM DDS_FACT_EMS_SMS_DSTR_TXN where time_dmns_key = concat(concat('5',decode(substr($$v_rpt_mth,5,2),'01',substr($$v_rpt_mth,1,4) - 1, '02', substr($$v_rpt_mth,1,4) - 1,'03', substr($$v_rpt_mth,1,4) - 1, substr($$v_rpt_mth,1,4))),'0000') and gnrl_stat_dmns_key in (39,40,41))
GROUP BY GNRL_STAT_DMNS_KEY, concat(concat('5',decode(substr($$v_rpt_mth,5,2),'01',substr($$v_rpt_mth,1,4) - 1, '02', substr($$v_rpt_mth,1,4) - 1,'03', substr($$v_rpt_mth,1,4) - 1, substr($$v_rpt_mth,1,4))),'0000'), DSTR_DMNS_KEY, CRT_DMNS_KEY;

-- [SOURCE_QUALIFIER] Step: apply_SQ_DPA_FACT_EMS_SMS_DSTR_TXN31
select GNRL_STAT_DMNS_KEY, 0 as TIME_DMNS_KEY, DSTR_DMNS_KEY, CRT_DMNS_KEY, SUM(TXN_CNT)
from
(SELECT 
GNRL_STAT_DMNS_KEY, DSTR_DMNS_KEY, CRT_DMNS_KEY, TXN_CNT
FROM DPA_FACT_EMS_SMS_DSTR_TXN where time_dmns_key = concat(concat('2',$$v_rpt_mth),'00')
union all
SELECT 
GNRL_STAT_DMNS_KEY, DSTR_DMNS_KEY, CRT_DMNS_KEY, TXN_CNT
FROM DDS_FACT_EMS_SMS_DSTR_TXN where time_dmns_key = 0 and gnrl_stat_dmns_key in (39,40,41))
GROUP BY GNRL_STAT_DMNS_KEY, 0, DSTR_DMNS_KEY, CRT_DMNS_KEY;

