-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_UNIT_STS1
SELECT blk.EMMS_BLK_KEY AS BLK_BK, TO_CHAR(unit.unit_flr_num)
FROM sor_hsm_unit unit, sor_hsm_blk blk
WHERE unit.blk_key = blk.blk_key;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_UNIT_STS
SELECT unit.EMMS_UNIT_KEY, unit.UNIT_TYPE_CODE, unit_sts.HSE_UNIT_TM_STS_CODE, blk.BLK_CODE, blk.BLK_TYPE_CODE, est.EST_CODE,
rgn.RGN_CODE, blk.EMMS_BLK_KEY
FROM SOR_HSM_UNIT unit, SOR_HSM_UNIT_STS unit_sts,
SOR_HSM_BLK blk, SOR_HSM_BLK_STS blk_sts, 
SOR_HSM_EST est,
SOR_HSM_EST_RGN_RLTN est_rgn,
SOR_HSM_RGN rgn
WHERE blk.BLK_KEY = blk_sts.BLK_KEY
AND unit.UNIT_KEY = unit_sts.UNIT_KEY
AND unit.BLK_KEY = blk.BLK_KEY
AND blk.EST_KEY = est.EST_KEY
AND est.EST_KEY = est_rgn.EST_KEY
AND est_rgn.RGN_KEY = rgn.RGN_KEY
AND unit_sts.HSE_UNIT_TM_STS_CODE IN ('OCPY','VCNT') 
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_rgn.BGN_DATE AND est_rgn.END_DATE
and rgn.rgn_type_code='RM';

