-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_CPM_ADTN_DEL
SELECT est.est_key, del_sts.ADTN_DEL_RSN_CATG_CODE || del_sts.ADTN_DEL_RSN_CODE,
del.MBR_ADTN_DEL_BK, del.MBR_ADTN_DEL_KEY
FROM SOR_HSM_EST est, 
SOR_HSM_BLK blk, SOR_HSM_BLK_STS blk_sts,
SOR_HSM_UNIT unit, SOR_HSM_UNIT_STS unit_sts,
SOR_EMS_TAM_TNCY_AGRMT tam, SOR_EMS_TAM_TNCY_AGRMT_STS tam_sts,
SOR_EMS_CPM_ADTN_DEL del, SOR_EMS_CPM_ADTN_DEL_STS del_sts,
SOR_EMS_CPM_CUST cust, SOR_EMS_CMM_HSE_SRVC_APLY srvc
WHERE blk.BLK_KEY = blk_sts.BLK_KEY
AND unit.UNIT_KEY = unit_sts.UNIT_KEY
AND tam.TNCY_AGRMT_KEY = tam_sts.TNCY_AGRMT_KEY
AND del.MBR_ADTN_DEL_KEY = del_sts.MBR_ADTN_DEL_KEY
AND blk.BLK_KEY = unit.BLK_KEY
AND blk.EST_KEY = est.EST_KEY
AND unit.UNIT_KEY = tam_sts.UNIT_KEY
AND tam.CUST_KEY = cust.CUST_KEY
AND cust.CUST_BK = del_sts.CUST_KEY
AND tam.HSE_SRVC_APLY_KEY = srvc.HSE_SRVC_APLY_KEY
AND srvc.HSE_SRVC_APLY_BK = del_sts.HSE_SRVC_APLY_KEY 
AND tam_sts.TNCY_AGRMT_STS_CODE = 'A'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN tam_sts.BGN_DATE AND tam_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN del_sts.BGN_DATE AND del_sts.END_DATE
and 1=2;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_CPM_ADTN_DEL_STS
select distinct
(select rpad(trim(substr(unit_addr_code, 2,4)),4) || rpad(trim(substr(unit_addr_code, 6,3)),3)
|| lpad(trim(substr(unit_addr_code, 9,5)),5) || rpad(substr(unit_addr_code,14,1),1)
|| rpad(substr(unit_addr_code,15,1),1) from sor_hsm_unit u
where u.unit_key = x.unit_key) unit_addr_code, 
cust_mbr_id_num, 
nvl(cust_mbr_dob_date,to_date(trim(substr(mbr_vals,1,8)),'YYYYMMDD')) cust_mbr_dob_date,
nvl(cust_mbr_rltn_code,substr(mbr_vals,9,2)) cust_mbr_rltn_code,
nvl(cust_mbr_gndr_code,substr(mbr_vals,11,1)) cust_mbr_gndr_code,
adtn_del_rsn_catg_code, adtn_del_rsn_code, adtn_del_date, rmk
from (
with dd as (
select distinct cust_key, hse_srvc_aply_key, hse_srvc_aply_type_code, cust_mbr_id_type_code, cust_mbr_id_num, adtn_del_date, adtn_del_rsn_catg_code, adtn_del_rsn_code
from sor_ems_cpm_adtn_del_sts where to_date('$$v_snsh_date', 'yyyymmdd') between bgn_date and end_date
and adtn_del_rsn_code is not null
and adtn_del_date between add_months(to_date('$$v_snsh_date', 'yyyymmdd'), -4) and add_months(to_date('$$v_snsh_date', 'yyyymmdd'), -1)
),
x1 as (
select dd.*, ps.cust_mbr_dob_date, ms.cust_mbr_rltn_code, ps.cust_mbr_gndr_code, ts.unit_key, '' rmk, '' mbr_vals 
from dd, sor_ems_cpm_cust c, sor_ems_cmm_hse_srvc_aply sa, sor_ems_cpm_cust_aply ca, sor_ems_tam_tncy_agrmt t, sor_ems_tam_tncy_agrmt_sts ts,
sor_ems_cpm_cust_aply_mbr m, sor_ems_cpm_cust_aply_mbr_sts ms, sor_ems_cpm_ptcl p, sor_ems_cpm_ptcl_sts ps 
where t.tncy_agrmt_key = ts.tncy_agrmt_key and to_date('$$v_snsh_date', 'yyyymmdd') between ts.bgn_date and ts.end_date
and m.cust_aply_mbr_key = ms.cust_aply_mbr_key and to_date('$$v_snsh_date', 'yyyymmdd') between ms.bgn_date and ms.end_date 
-- ptcl mark del
and p.ptcl_key = ps.ptcl_key and ps.bgn_date = (select max(bgn_date) from sor_ems_cpm_ptcl_sts where ptcl_key = p.ptcl_key and bgn_date <= to_date('$$v_snsh_date', 'yyyymmdd')) 
and ca.cust_key = c.cust_key and ca.hse_srvc_aply_key = sa.hse_srvc_aply_key
and c.cust_key = t.cust_key and sa.hse_srvc_aply_key = t.hse_srvc_aply_key
and ca.cust_aply_key = m.cust_aply_key
and m.ptcl_key = p.ptcl_key
and dd.cust_key = c.cust_bk and dd.hse_srvc_aply_key = sa.hse_srvc_aply_bk 
and dd.hse_srvc_aply_type_code = m.hse_srvc_aply_type_code 
and dd.cust_mbr_id_type_code = m.cust_mbr_id_type_code 
and dd.cust_mbr_id_num = m.cust_mbr_id_num 
),
xd as (
select dd.*, null cust_mbr_dob_date, null cust_mbr_rltn_code, null cust_mbr_gndr_code, 
    (select ts.unit_key from sor_ems_cpm_cust c, sor_ems_cmm_hse_srvc_aply sa, sor_ems_tam_tncy_agrmt t, sor_ems_tam_tncy_agrmt_sts ts
      where t.tncy_agrmt_key = ts.tncy_agrmt_key and to_date('$$v_snsh_date', 'yyyymmdd') between ts.bgn_date and ts.end_date 
        and c.cust_key = t.cust_key and sa.hse_srvc_aply_key = t.hse_srvc_aply_key
        and dd.cust_key = c.cust_bk and dd.hse_srvc_aply_key = sa.hse_srvc_aply_bk), '*' rmk,
    (select rpad(to_char(max(cust_mbr_dob_date), 'YYYYMMDD')||' ', 8, ' ') || rpad(max(cust_mbr_rltn_code)||' ', 2, ' ') || rpad(max(cust_mbr_gndr_code)||' ', 1, ' ') || rpad(max(hse_srvc_aply_type_code)||' ', 1, ' ')
       from sor_ems_cpm_cust c, sor_ems_cmm_hse_srvc_aply sa, sor_ems_cpm_cust_aply ca, sor_ems_cpm_cust_aply_mbr m, sor_ems_cpm_cust_aply_mbr_sts ms
      where m.cust_aply_mbr_key = ms.cust_aply_mbr_key and to_date('$$v_snsh_date', 'yyyymmdd') between ms.bgn_date and ms.end_date
        and c.cust_key = ca.cust_key and sa.hse_srvc_aply_key = ca.hse_srvc_aply_key
        and m.cust_aply_key = ca.cust_aply_key
        -- skip check hse_srvc_aply_type_code 
        and dd.cust_key = c.cust_bk and dd.hse_srvc_aply_key = sa.hse_srvc_aply_bk
        and m.cust_mbr_id_type_code = dd.cust_mbr_id_type_code
        and m.cust_mbr_id_num = dd.cust_mbr_id_num) mbr_vals
  from dd
where (cust_key, hse_srvc_aply_key, hse_srvc_aply_type_code, cust_mbr_id_type_code, cust_mbr_id_num, adtn_del_date, adtn_del_rsn_catg_code, adtn_del_rsn_code) not in
(select cust_key, hse_srvc_aply_key, hse_srvc_aply_type_code, cust_mbr_id_type_code, cust_mbr_id_num, adtn_del_date, adtn_del_rsn_catg_code, adtn_del_rsn_code
   from x1)
)
select * from x1 union all select * from xd
) x order by 1, 2;

-- [SELECT] Step: read_LKP_RGN_DSTR
-- Connection: DPA
SELECT est.EST_KEY as EST_KEY, rgn.RGN_CODE as RGN_CODE, dstr.DSTR_CODE as DSTR_CODE
FROM SOR_HSM_EST est,
SOR_HSM_RGN rgn, SOR_HSM_EST_RGN_RLTN est_rgn,
SOR_HSM_DSTR dstr, SOR_HSM_EST_DSTR_RLTN est_dstr
WHERE est.EST_KEY = est_rgn.EST_KEY
AND est_rgn.RGN_KEY = rgn.RGN_KEY
AND est.EST_KEY = est_dstr.EST_KEY
AND est_dstr.DSTR_KEY = dstr.DSTR_KEY
AND dstr.DSTR_TYPE_CODE = 'DIST'
AND rgn.RGN_TYPE_CODE='RM'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_rgn.BGN_DATE AND est_rgn.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_dstr.BGN_DATE AND est_dstr.END_DATE;

