-- Mapping: M_S5_DPA_SUMMARIZE_FACT_EMS_PRH_ABU
-- =============================================================================

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_TYPE_CODE
SELECT
RGN.RGN_CODE,
'T'||ABU_STS.ABU_TYPE_CODE,
 SUM(CASE WHEN(TRUNC(ABU_STS.ABU_RSLT_UPD_DATE,'MM')=TRUNC(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 'MM')                              
 OR TRUNC(ABU_STS.ABU_STS_UPD_DATE,'MM')=TRUNC(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 'MM')
 ) THEN 1 ELSE 0 END) -                                                                                     
 SUM(CASE WHEN(ABU_STS.ABU_STS_CODE='CONF' AND ABU_STS.ABU_WTHDRW_IND='Y'                                            
 AND TRUNC(ABU_STS.ABU_STS_UPD_DATE,'MM')=TRUNC(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 'MM')                             
 ) THEN 1 ELSE 0 END) AS CNT                 
FROM 
SOR_EMS_ABU_TNT_ABU ABU,
SOR_EMS_ABU_TNT_ABU_STS ABU_STS,
SOR_EMS_TAM_TNCY_AGRMT TNCY,
SOR_EMS_TAM_TNCY_AGRMT_STS TNCY_STS,
SOR_HSM_UNIT UNIT,
SOR_HSM_UNIT_STS UNIT_STS,
SOR_HSM_BLK BLK,
SOR_HSM_BLK_STS BLK_STS,
SOR_HSM_EST EST,
SOR_HSM_EST_DSTR_RLTN EST_DSTR_RLTN,
SOR_HSM_DSTR DSTR,
SOR_HSM_RGN RGN
WHERE 
ABU.ABU_KEY = ABU_STS.ABU_KEY
AND TNCY.TNCY_AGRMT_KEY = ABU_STS.TNCY_AGRMT_KEY
AND TNCY.TNCY_AGRMT_KEY = TNCY_STS.TNCY_AGRMT_KEY
AND UNIT.UNIT_KEY = UNIT_STS.UNIT_KEY
AND UNIT.UNIT_KEY = TNCY_STS.UNIT_KEY
AND BLK.BLK_KEY = BLK_STS.BLK_KEY
AND BLK.BLK_KEY = UNIT.BLK_KEY
AND BLK.EST_KEY = EST.EST_KEY
AND EST.EST_KEY = EST_DSTR_RLTN.EST_KEY
AND EST_DSTR_RLTN.DSTR_KEY = DSTR.DSTR_KEY
AND RGN.RGN_KEY = DSTR.RGN_KEY
AND RGN.RGN_TYPE_CODE = 'RM'                                                                   
AND NVL(ABU.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(TNCY.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(UNIT.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(BLK.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(EST.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(DSTR.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(RGN.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN ABU_STS.BGN_DATE AND ABU_STS.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TNCY_STS.BGN_DATE AND TNCY_STS.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN UNIT_STS.BGN_DATE AND UNIT_STS.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BLK_STS.BGN_DATE AND BLK_STS.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN EST_DSTR_RLTN.BGN_DATE AND EST_DSTR_RLTN.END_DATE
AND ((ABU_STS.ABU_STS_CODE = 'CONF' AND ABU_STS.ABU_WTHDRW_IND = 'N') OR                                              
      ((ABU_STS.ABU_STS_CODE = 'CLOS' AND ABU_STS.ABU_WTHDRW_IND = 'N') OR                                              
       (ABU_STS.ABU_STS_CODE = 'CONF' AND ABU_STS.ABU_WTHDRW_IND = 'Y')
      )
    )   
GROUP BY RGN.RGN_CODE, ABU_STS.ABU_TYPE_CODE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_SCP_CODE
SELECT
RGN.RGN_CODE,
'S'||ABU_STS.ABU_SCP_CODE, 
 SUM(CASE WHEN(TRUNC(ABU_STS.ABU_RSLT_UPD_DATE,'MM')=TRUNC(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 'MM')                              
 OR TRUNC(ABU_STS.ABU_STS_UPD_DATE,'MM')=TRUNC(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 'MM')
 ) THEN 1 ELSE 0 END) -                                                                                     
 SUM(CASE WHEN(ABU_STS.ABU_STS_CODE='CONF' AND ABU_STS.ABU_WTHDRW_IND='Y'                                            
 AND TRUNC(ABU_STS.ABU_STS_UPD_DATE,'MM')=TRUNC(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 'MM')                             
 ) THEN 1 ELSE 0 END) AS CNT                 
FROM 
SOR_EMS_ABU_TNT_ABU ABU,
SOR_EMS_ABU_TNT_ABU_STS ABU_STS,
SOR_EMS_TAM_TNCY_AGRMT TNCY,
SOR_EMS_TAM_TNCY_AGRMT_STS TNCY_STS,
SOR_HSM_UNIT UNIT,
SOR_HSM_UNIT_STS UNIT_STS,
SOR_HSM_BLK BLK,
SOR_HSM_BLK_STS BLK_STS,
SOR_HSM_EST EST,
SOR_HSM_EST_DSTR_RLTN EST_DSTR_RLTN,
SOR_HSM_DSTR DSTR,
SOR_HSM_RGN RGN
WHERE 
ABU.ABU_KEY = ABU_STS.ABU_KEY
AND TNCY.TNCY_AGRMT_KEY = ABU_STS.TNCY_AGRMT_KEY
AND TNCY.TNCY_AGRMT_KEY = TNCY_STS.TNCY_AGRMT_KEY
AND UNIT.UNIT_KEY = UNIT_STS.UNIT_KEY
AND UNIT.UNIT_KEY = TNCY_STS.UNIT_KEY
AND BLK.BLK_KEY = BLK_STS.BLK_KEY
AND BLK.BLK_KEY = UNIT.BLK_KEY
AND BLK.EST_KEY = EST.EST_KEY
AND EST.EST_KEY = EST_DSTR_RLTN.EST_KEY
AND EST_DSTR_RLTN.DSTR_KEY = DSTR.DSTR_KEY                                                                 
AND DSTR.RGN_KEY = RGN.RGN_KEY
AND RGN.RGN_TYPE_CODE = 'RM'  
AND NVL(ABU.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(TNCY.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(UNIT.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(BLK.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(EST.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(DSTR.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(RGN.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN ABU_STS.BGN_DATE AND ABU_STS.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TNCY_STS.BGN_DATE AND TNCY_STS.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN UNIT_STS.BGN_DATE AND UNIT_STS.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BLK_STS.BGN_DATE AND BLK_STS.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN EST_DSTR_RLTN.BGN_DATE AND EST_DSTR_RLTN.END_DATE
AND ((ABU_STS.ABU_STS_CODE = 'CONF' AND ABU_STS.ABU_WTHDRW_IND = 'N') OR                                              
      ((ABU_STS.ABU_STS_CODE = 'CLOS' AND ABU_STS.ABU_WTHDRW_IND = 'N') OR                                              
       (ABU_STS.ABU_STS_CODE = 'CONF' AND ABU_STS.ABU_WTHDRW_IND = 'Y')
      )
    )   
GROUP BY RGN.RGN_CODE, ABU_STS.ABU_SCP_CODE;

