sor_ems_cpm_cust_aply_mbr mbr, sor_ems_cpm_cust_aply_mbr_sts mbr_sts,
sor_ems_cpm_cust_aply aply, sor_ems_cpm_cust_aply_sts aply_sts
WHERE mbr.cust_aply_mbr_key = mbr_sts.cust_aply_mbr_key
