-- [SOURCE_QUALIFIER] Step: apply_Total_No_of_Existing_Tenancies
SELECT RGN_CODE, DSTR_CODE
FROM
(
SELECT 
/*+ FULL(ptcl) FULL(ptcl_sts) FULL(mbr) FULL(mbr_sts) FULL(tncy) FULL(tncy_sts) */
DISTINCT est.EST_CODE, rgn.RGN_CODE, dstr.DSTR_CODE, tncy.CUST_KEY,
tncy.HSE_SRVC_APLY_KEY
FROM SOR_EMS_CPM_PTCL ptcl, SOR_EMS_CPM_PTCL_STS ptcl_sts, 
SOR_EMS_CPM_CUST_APLY_MBR mbr, SOR_EMS_CPM_CUST_APLY_MBR_STS mbr_sts,
SOR_EMS_TAM_TNCY_AGRMT tncy, SOR_EMS_TAM_TNCY_AGRMT_STS tncy_sts,
SOR_HSM_UNIT unit, SOR_HSM_UNIT_STS unit_sts,
SOR_HSM_BLK blk, SOR_HSM_BLK_STS blk_sts,
SOR_HSM_EST est,
SOR_HSM_EST_DSTR_RLTN est_dstr,
SOR_HSM_DSTR dstr,
SOR_HSM_RGN rgn,
SOR_HSM_EST_RGN_RLTN est_rgn
WHERE ptcl.PTCL_KEY = ptcl_sts.PTCL_KEY
AND mbr.CUST_APLY_MBR_KEY = mbr_sts.CUST_APLY_MBR_KEY
AND tncy.TNCY_AGRMT_KEY = tncy_sts.TNCY_AGRMT_KEY
AND unit.UNIT_KEY = unit_sts.UNIT_KEY
AND blk.BLK_KEY = blk_sts.BLK_KEY
AND SUBSTR(mbr.CUST_APLY_MBR_BK,1,9) || SUBSTR(mbr.CUST_APLY_MBR_BK,24,15)= tncy.TNCY_AGRMT_BK
AND tncy_sts.UNIT_KEY = unit.UNIT_KEY
AND unit.BLK_KEY = blk.BLK_KEY
AND blk.EST_KEY = est.EST_KEY
AND est.EST_KEY = est_dstr.EST_KEY
AND est_dstr.DSTR_KEY = dstr.DSTR_KEY
AND est.EST_KEY = est_rgn.EST_KEY
AND est_rgn.RGN_KEY = rgn.RGN_KEY
AND est.EST_TYPE_CODE = 'E'
AND dstr.DSTR_TYPE_CODE = 'DIST'
AND mbr.HSE_SRVC_APLY_TYPE_CODE = 'T'
AND mbr_sts.CUST_APLY_MBR_STS_CODE = 'A'
AND ptcl_sts.CUST_MBR_DOB_DATE <= TO_DATE('$$v_snsh_date', 'YYYYMMDD')
AND tncy_sts.TNCY_AGRMT_TM_STS_CODE = 'A'
AND mbr_sts.CUST_MBR_UP_IND = 'N'
AND mbr.CUST_MBR_ID_TYPE_CODE = ptcl.CUST_MBR_ID_TYPE_CODE
AND mbr.CUST_MBR_ID_NUM = ptcl.CUST_MBR_ID_NUM 
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN ptcl_sts.BGN_DATE AND ptcl_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN mbr_sts.BGN_DATE AND mbr_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN tncy_sts.BGN_DATE AND tncy_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_dstr.BGN_DATE AND est_dstr.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_rgn.BGN_DATE AND est_rgn.END_DATE
);

-- [SOURCE_QUALIFIER] Step: apply_Biennial_Declaration_Cycle
SELECT DISTINCT rgn.RGN_CODE, dstr.DSTR_CODE, cycl_sts.BD_CYCL_BGN_DATE, cycl_sts.BD_CYCL_END_DATE 
FROM SOR_EMS_DCL_BD_CYCL cycl, SOR_EMS_DCL_BD_CYCL_STS cycl_sts,
SOR_HSM_EST_RGN_RLTN est_rgn,
SOR_HSM_EST_DSTR_RLTN est_dstr,
SOR_HSM_RGN rgn,
SOR_HSM_DSTR dstr
WHERE cycl.BD_CYCL_KEY = cycl_sts.BD_CYCL_KEY
AND cycl_sts.EST_KEY = est_rgn.EST_KEY
AND cycl_sts.EST_KEY = est_dstr.EST_KEY
AND est_rgn.RGN_KEY = rgn.RGN_KEY
AND est_dstr.DSTR_KEY = dstr.DSTR_KEY
AND dstr.DSTR_TYPE_CODE = 'DIST'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cycl_sts.BGN_DATE AND cycl_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_rgn.BGN_DATE AND est_rgn.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_dstr.BGN_DATE AND est_dstr.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cycl_sts.BD_CYCL_BGN_DATE AND cycl_sts.BD_CYCL_END_DATE;

