-- =============================================================================

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_EST
SELECT 
/*+ FULL(aply) FULL(aply_sts) FULL(tncy) FULL(tncy_sts) */
est.est_type_code, est.est_code, unit.unit_addr_code, unit.unit_type_code, 
unit.unit_ifa_area, aply_sts.cust_fmly_size_num, aply_sts.cust_aem_ind,
tncy_sts.tncy_agrmt_cmnc_date, tncy_sts.tncy_agrmt_trmt_date, aply.cust_key
FROM sor_hsm_est est, sor_hsm_blk blk, sor_ems_tam_tncy_agrmt tncy,
sor_ems_tam_tncy_agrmt_sts tncy_sts, sor_hsm_unit unit, sor_hsm_unit_sts unit_sts,
sor_ems_cpm_cust_aply aply, sor_ems_cpm_cust_aply_sts aply_sts
WHERE tncy.tncy_agrmt_key = tncy_sts.tncy_agrmt_key AND unit.unit_key = unit_sts.unit_key
AND aply.cust_aply_key = aply_sts.cust_aply_key AND est.est_key = blk.est_key
AND blk.blk_key = unit.blk_key AND tncy_sts.unit_key = unit.unit_key
AND tncy.cust_key = aply.cust_key AND tncy.hse_srvc_aply_key = aply.hse_srvc_aply_key
AND tncy_sts.tncy_agrmt_sts_code = 'A' AND tncy_sts.tncy_agrmt_cmnc_date IS NOT NULL
AND ((aply_sts.cust_fmly_size_num = 1 AND unit_ifa_area > 25) OR
(aply_sts.cust_fmly_size_num = 2 AND unit.unit_ifa_area > 35) OR
(aply_sts.cust_fmly_size_num = 3 AND unit.unit_ifa_area > 44) OR
(aply_sts.cust_fmly_size_num = 4 AND unit.unit_ifa_area > 56) OR
(aply_sts.cust_fmly_size_num = 5 AND unit.unit_ifa_area > 62) OR
(aply_sts.cust_fmly_size_num = 6 AND unit.unit_ifa_area > 71))
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN tncy_sts.bgn_date AND tncy_sts.end_date
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.bgn_date AND unit_sts.end_date
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN aply_sts.bgn_date AND aply_sts.end_date;

-- [SELECT] Step: read_LKP_SOR_CUST_DSBL
-- Connection: DPA
select TO_CHAR(COUNT(dsbl.dsbl_catg_code)) as DSBL_CATG_CODE, mbr.cust_key as CUST_KEY from sor_ems_cpm_dsbl dsbl, SOR_EMS_CPM_CUST_MBR mbr
where dsbl.ptcl_key = mbr.ptcl_key
group by mbr.cust_key;

-- [SELECT] Step: read_LKPTRANS
-- Connection: DPA
select a.unit_addr_code as UNIT_CODE_ADDR, 
(case when(a.IND = 0) then NULL
when(a.IND <> 0 and a.IND = b.fmly_size_num) then 'Y'
else 'P' end) as CUST_AEM_IND
from
(SELECT unit.unit_addr_code, tncy.cust_key, tncy.hse_srvc_aply_key, sum(
case when(ptcl_sts.CUST_MBR_DOB_DATE <= add_months(to_date('$$v_snsh_date','yyyymmdd'), - 720)) then 1 else 0 end) as IND
FROM SOR_EMS_CPM_CUST_APLY_MBR mbr, SOR_EMS_CPM_CUST_APLY_MBR_STS mbr_sts,
SOR_EMS_TAM_TNCY_AGRMT tncy, SOR_EMS_TAM_TNCY_AGRMT_STS tncy_sts,
SOR_EMS_CPM_CUST_APLY aply,
SOR_HSM_UNIT unit, SOR_HSM_BLK blk, SOR_HSM_EST est, 
SOR_HSM_EST_DSTR_RLTN ed, SOR_HSM_DSTR dstr,
sor_ems_cpm_ptcl ptcl, sor_ems_cpm_ptcl_sts ptcl_sts
WHERE mbr.CUST_APLY_MBR_KEY = mbr_sts.CUST_APLY_MBR_KEY
AND tncy.TNCY_AGRMT_KEY = tncy_sts.TNCY_AGRMT_KEY
AND mbr.CUST_APLY_KEY = aply.CUST_APLY_KEY
AND aply.CUST_KEY = tncy.CUST_KEY
AND aply.HSE_SRVC_APLY_KEY = tncy.HSE_SRVC_APLY_KEY
AND tncy_sts.UNIT_KEY = unit.UNIT_KEY
AND unit.BLK_KEY = blk.BLK_KEY
AND blk.EST_KEY = est.EST_KEY
AND est.EST_KEY = ed.EST_KEY
AND ed.DSTR_KEY = dstr.DSTR_KEY
AND est.EST_TYPE_CODE = 'E'
AND dstr.DSTR_TYPE_CODE = 'DIST'
AND mbr.HSE_SRVC_APLY_TYPE_CODE = 'T'
AND mbr_sts.CUST_APLY_MBR_STS_CODE = 'A'
and tncy_sts.TNCY_AGRMT_TM_STS_CODE = 'A' and mbr_sts.CUST_MBR_UP_IND = 'N' 
and mbr.CUST_MBR_ID_TYPE_CODE=ptcl.CUST_MBR_ID_TYPE_CODE 
and mbr.CUST_MBR_ID_NUM=ptcl.CUST_MBR_ID_NUM 
and ptcl.PTCL_KEY=ptcl_sts.PTCL_KEY 
and TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN ptcl_sts.BGN_DATE AND ptcl_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN mbr_sts.BGN_DATE AND mbr_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN tncy_sts.BGN_DATE AND tncy_sts.END_DATE
GROUP BY unit.unit_addr_code, tncy.cust_key, tncy.hse_srvc_aply_key)a,
(select aply.cust_key, aply.hse_srvc_aply_key, count(*) as fmly_size_num
from sor_ems_cpm_cust_aply_mbr mbr, sor_ems_cpm_cust_aply_mbr_sts mbr_sts,
sor_ems_cpm_cust_aply aply, sor_ems_cpm_cust_aply_sts aply_sts
where mbr.cust_aply_mbr_key = mbr_sts.cust_aply_mbr_key
and mbr.cust_aply_key = aply.cust_aply_key
and aply.cust_aply_key = aply_sts.cust_aply_key
AND mbr.HSE_SRVC_APLY_TYPE_CODE = 'T'
AND mbr_sts.CUST_APLY_MBR_STS_CODE = 'A'
and mbr_sts.CUST_MBR_UP_IND = 'N' 
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN mbr_sts.BGN_DATE AND mbr_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN aply_sts.BGN_DATE AND aply_sts.END_DATE
group by aply.cust_key, aply.hse_srvc_aply_key)b
where a.cust_key = b.cust_key and a.hse_srvc_aply_key = b.hse_srvc_aply_key;

