-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_DSTR
SELECT
/*+ FULL(aply) FULL(aply_sts) FULL(tncy) FULL(tncy_sts) */
est.EST_KEY, est.EST_CODE, blk.BLK_CODE, aply_sts.CUST_FMLY_SIZE_NUM ,
tncy.CUST_KEY, tncy.HSE_SRVC_APLY_KEY
FROM
SOR_EMS_TAM_TNCY_AGRMT tncy, SOR_EMS_TAM_TNCY_AGRMT_STS tncy_sts,
SOR_EMS_CPM_CUST_APLY aply, SOR_EMS_CPM_CUST_APLY_STS aply_sts,
SOR_HSM_UNIT unit, SOR_HSM_UNIT_STS unit_sts,
SOR_HSM_RGN rgn,
SOR_HSM_EST_RGN_RLTN est_rgn,
SOR_HSM_DSTR dstr,
SOR_HSM_EST_DSTR_RLTN est_dstr,
SOR_HSM_EST est,
SOR_HSM_BLK blk
WHERE 
tncy.TNCY_AGRMT_KEY = tncy_sts.TNCY_AGRMT_KEY
AND aply.CUST_APLY_KEY = aply_sts.CUST_APLY_KEY
AND unit.UNIT_KEY = unit_sts.UNIT_KEY
AND aply.HSE_SRVC_APLY_KEY = tncy.HSE_SRVC_APLY_KEY
AND aply.CUST_KEY = tncy.CUST_KEY
AND tncy_sts.UNIT_KEY = unit.UNIT_KEY
AND dstr.DSTR_KEY = est_dstr.DSTR_KEY
AND est.EST_KEY = est_dstr.EST_KEY
AND est.EST_KEY = blk.EST_KEY
AND est.EST_KEY = est_rgn.EST_KEY
AND rgn.RGN_KEY = est_rgn.RGN_KEY
AND blk.BLK_KEY = unit.BLK_KEY 
--AND area.cust_key = tncy.CUST_KEY
--AND area.hse_srvc_aply_key = tncy.HSE_SRVC_APLY_KEY
--AND NVL(tncy.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
--AND NVL(aply.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
--AND NVL(unit.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(rgn.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(dstr.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(est.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND NVL(blk.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND tncy_sts.TNCY_AGRMT_TM_STS_CODE = 'A'
AND est.EST_TYPE_CODE = 'E' 
AND SUBSTR(est.EST_CODE,1,1) <> '9'
AND dstr.DSTR_TYPE_CODE = 'DIST' 
AND RGN.RGN_TYPE_CODE = 'RM'
AND aply_sts.CUST_FMLY_SIZE_NUM IS NOT NULL
AND aply_sts.CUST_FMLY_SIZE_NUM !=  0  -- LVNG_DNSTY
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN tncy_sts.BGN_DATE AND tncy_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN aply_sts.BGN_DATE AND aply_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_rgn.BGN_DATE AND est_rgn.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_dstr.BGN_DATE AND est_dstr.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_DSTR1
SELECT  -- total ifa area = main room + additional room 
CUST_KEY, HSE_SRVC_APLY_KEY, SUM(unit_ifa_area) "HSE_UNIT_IFA_AREA"
FROM (
SELECT  -- additional room logic
t.cust_key, t.hse_srvc_aply_key, unit_ifa_area 
FROM
SOR_EMS_TAM_ADTN_ROOM rm, SOR_EMS_TAM_ADTN_ROOM_STS rm_sts,
SOR_HSM_UNIT unit, SOR_HSM_UNIT_STS unit_sts,
SOR_EMS_TAM_TNCY_AGRMT t,  SOR_EMS_TAM_TNCY_AGRMT_STS t_sts
WHERE 
rm.ADTN_ROOM_KEY = rm_sts.ADTN_ROOM_KEY
AND unit.UNIT_KEY = unit_sts.UNIT_KEY
AND unit.UNIT_KEY = rm.UNIT_KEY
AND rm .TNCY_AGRMT_KEY = t.TNCY_AGRMT_KEY
AND t.TNCY_AGRMT_KEY = t_sts.TNCY_AGRMT_KEY
AND TNCY_AGRMT_TM_STS_CODE = 'A'
--AND NVL(rm.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'  
--AND NVL(unit.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'  
--AND NVL(t_sts.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'  
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN rm_sts.BGN_DATE AND rm_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN t_sts.BGN_DATE AND t_sts.END_DATE
UNION ALL ( 
SELECT -- main room
tncy.CUST_KEY, tncy.HSE_SRVC_APLY_KEY, unit.UNIT_IFA_AREA 
FROM
SOR_HSM_UNIT unit, SOR_HSM_UNIT_STS unit_sts,
SOR_EMS_TAM_TNCY_AGRMT tncy, SOR_EMS_TAM_TNCY_AGRMT_STS tncy_sts
WHERE unit.UNIT_KEY = unit_sts.UNIT_KEY
AND tncy.TNCY_AGRMT_KEY = tncy_sts.TNCY_AGRMT_KEY
AND tncy_sts.UNIT_KEY = unit.UNIT_KEY
AND tncy_sts.TNCY_AGRMT_TM_STS_CODE = 'A'
--AND NVL(unit.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
--AND NVL(tncy.LAST_REC_TXN_TYPE_CODE,'I') <> 'D'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN tncy_sts.BGN_DATE AND tncy_sts.END_DATE
) -- end union
) -- end select
GROUP BY cust_key, hse_srvc_aply_key;

-- [SELECT] Step: read_LKP_RGN_DSTR
-- Connection: DPA
SELECT est.EST_KEY as EST_KEY, rgn.RGN_CODE as RGN_CODE, dstr.DSTR_CODE as DSTR_CODE
FROM SOR_HSM_EST est,
SOR_HSM_RGN rgn, SOR_HSM_EST_RGN_RLTN est_rgn,
SOR_HSM_DSTR dstr, SOR_HSM_EST_DSTR_RLTN est_dstr
WHERE est.EST_KEY = est_rgn.EST_KEY
AND est_rgn.RGN_KEY = rgn.RGN_KEY
AND est.EST_KEY = est_dstr.EST_KEY
AND est_dstr.DSTR_KEY = dstr.DSTR_KEY
AND dstr.DSTR_TYPE_CODE = 'DIST'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_rgn.BGN_DATE AND est_rgn.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN est_dstr.BGN_DATE AND est_dstr.END_DATE;

