-- [SOURCE_QUALIFIER] Step: apply_Self_Withdrawal
SELECT est.EST_KEY, trf_sts.REF_CASE_TYPE_CODE, trf_sts.TFR_RSN_CODE
FROM SOR_EMS_TRF_REF_CASE trf, SOR_EMS_TRF_REF_CASE_STS trf_sts,
SOR_EMS_PHA_APLY aply, SOR_EMS_PHA_APLY_STS aply_sts,
SOR_HSM_UNIT unit, SOR_HSM_UNIT_STS unit_sts,
SOR_HSM_BLK blk, SOR_HSM_BLK_STS blk_sts,
SOR_HSM_EST est
WHERE aply_sts.TNCY_AGRMT_KEY = trf_sts.TNCY_AGRMT_KEY
AND trf.REF_CASE_KEY = trf_sts.REF_CASE_KEY
AND aply.APLY_KEY = aply_sts.APLY_KEY
AND unit.UNIT_KEY = unit_sts.UNIT_KEY
AND blk.BLK_KEY = blk_sts.BLK_KEY
AND trf_sts.UNIT_KEY = unit.UNIT_KEY
AND unit.BLK_KEY = blk.BLK_KEY
AND blk.EST_KEY = est.EST_KEY
AND aply_sts.PRH_APLY_STS_CODE = 'P'
AND trf_sts.REF_CASE_TYPE_CODE IN ('ITR','XTR')
AND trf_sts.LAST_REC_TXN_TYPE_CODE = 'D'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN trf_sts.BGN_DATE AND trf_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN aply_sts.BGN_DATE AND aply_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN unit_sts.BGN_DATE AND unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE;

