-- [SOURCE_QUALIFIER] Step: apply_SQ_NEW
WITH a AS
(SELECT hist.EST_KEY, hist.BLK_KEY, EST_CODE, BLK_CODE, UNIT_IFA_AREA, UNIT_TYPE_CODE, RENT_SCHD_BGN_DATE,
UNIT_NET_RENT_AMT, UNIT_NET_RATE_AMT, UNIT_NET_RENT_AMT + UNIT_NET_RATE_AMT AS INCL_RENT,
UNIT_ENV_CODE, TNT_RENT_CODE_CATG_CODE, TOT_AFCT_UNIT_CNT
FROM SOR_EMS_RFX_RENT_SCHD_HIST hist, SOR_EMS_RFX_RENT_SCHD_HIST_STS hist_sts,
SOR_HSM_EST est, SOR_HSM_BLK blk 
WHERE hist.RENT_SCHD_AMND_HIST_KEY = hist_sts.RENT_SCHD_AMND_HIST_KEY
AND hist.EST_KEY = est.EMMS_EST_KEY
AND hist.BLK_KEY = blk.EMMS_BLK_KEY
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN hist_sts.BGN_DATE AND hist_sts.END_DATE
AND TNT_RENT_CODE_CATG_CODE = 'N')
SELECT a.EST_CODE, a.BLK_CODE, a.UNIT_TYPE_CODE, a.UNIT_IFA_AREA, a.UNIT_ENV_CODE,
a.TOT_AFCT_UNIT_CNT, a.UNIT_NET_RATE_AMT, a.UNIT_NET_RENT_AMT, a.RENT_SCHD_BGN_DATE,
a.TNT_RENT_CODE_CATG_CODE
FROM a, (SELECT EST_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE, RENT_SCHD_BGN_DATE
FROM (SELECT a.EST_KEY, a.UNIT_IFA_AREA, a.UNIT_TYPE_CODE, a.RENT_SCHD_BGN_DATE, a.INCL_RENT
FROM a, (SELECT b.EST_KEY, b.UNIT_IFA_AREA, b.RENT_SCHD_BGN_DATE
FROM (SELECT EST_KEY, BLK_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE,
MAX(RENT_SCHD_BGN_DATE) AS RENT_SCHD_BGN_DATE, UNIT_ENV_CODE
FROM a
GROUP BY EST_KEY, BLK_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE, UNIT_ENV_CODE) b
GROUP BY b.EST_KEY, b.UNIT_IFA_AREA, b.RENT_SCHD_BGN_DATE
HAVING COUNT(*) > 1) c
WHERE a.EST_KEY = c.EST_KEY AND a.UNIT_IFA_AREA = c.UNIT_IFA_AREA
AND a.RENT_SCHD_BGN_DATE = c.RENT_SCHD_BGN_DATE
GROUP BY a.EST_KEY, a.UNIT_IFA_AREA, a.UNIT_TYPE_CODE, a.INCL_RENT, a.RENT_SCHD_BGN_DATE)
GROUP BY EST_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE, RENT_SCHD_BGN_DATE
HAVING COUNT(*) > 1) d
WHERE a.EST_KEY = d.EST_KEY AND a.UNIT_IFA_AREA = d.UNIT_IFA_AREA
AND a.UNIT_TYPE_CODE = d.UNIT_TYPE_CODE AND a.RENT_SCHD_BGN_DATE = d.RENT_SCHD_BGN_DATE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_EXISTING
WITH a AS
(SELECT hist.EST_KEY, hist.BLK_KEY, est.EST_CODE, blk.BLK_CODE, hist.UNIT_IFA_AREA, hist_sts.UNIT_TYPE_CODE, hist_sts.RENT_SCHD_BGN_DATE,
hist_sts.UNIT_NET_RENT_AMT, hist_sts.UNIT_NET_RATE_AMT, hist_sts.UNIT_NET_RENT_AMT + hist_sts.UNIT_NET_RATE_AMT AS INCL_RENT,
hist.UNIT_ENV_CODE, hist.TNT_RENT_CODE_CATG_CODE, hist_sts.TOT_AFCT_UNIT_CNT
FROM SOR_EMS_RFX_RENT_SCHD_HIST hist, SOR_EMS_RFX_RENT_SCHD_HIST_STS hist_sts,
SOR_HSM_EST est, SOR_HSM_BLK blk 
WHERE hist.RENT_SCHD_AMND_HIST_KEY = hist_sts.RENT_SCHD_AMND_HIST_KEY
AND hist.EST_KEY = est.EMMS_EST_KEY
AND hist.BLK_KEY = blk.EMMS_BLK_KEY
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN hist_sts.BGN_DATE AND hist_sts.END_DATE
AND hist.TNT_RENT_CODE_CATG_CODE = 'N')
SELECT a.EST_CODE, a.BLK_CODE, a.UNIT_TYPE_CODE, a.UNIT_IFA_AREA, a.UNIT_ENV_CODE, 
a.TOT_AFCT_UNIT_CNT,  a.UNIT_NET_RATE_AMT, a.UNIT_NET_RENT_AMT, a.RENT_SCHD_BGN_DATE,
a.TNT_RENT_CODE_CATG_CODE
FROM a, (SELECT a.EST_KEY, a.BLK_KEY, a.UNIT_IFA_AREA, a.UNIT_TYPE_CODE, 
MAX(a.RENT_SCHD_BGN_DATE) AS RENT_SCHD_BGN_DATE, a.UNIT_ENV_CODE
FROM a, (SELECT a.*
FROM a, (SELECT EST_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE, RENT_SCHD_BGN_DATE
FROM (SELECT a.EST_KEY, a.UNIT_IFA_AREA, a.UNIT_TYPE_CODE, a.RENT_SCHD_BGN_DATE, a.INCL_RENT
FROM a, (SELECT b.EST_KEY, b.UNIT_IFA_AREA, b.RENT_SCHD_BGN_DATE
FROM (SELECT EST_KEY, BLK_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE,
MAX(RENT_SCHD_BGN_DATE) AS RENT_SCHD_BGN_DATE, UNIT_ENV_CODE
FROM a
GROUP BY EST_KEY, BLK_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE, UNIT_ENV_CODE) b
GROUP BY b.EST_KEY, b.UNIT_IFA_AREA, b.RENT_SCHD_BGN_DATE
HAVING COUNT(*) > 1) c
WHERE a.EST_KEY = c.EST_KEY AND a.UNIT_IFA_AREA = c.UNIT_IFA_AREA
AND a.RENT_SCHD_BGN_DATE = c.RENT_SCHD_BGN_DATE
GROUP BY a.EST_KEY, a.UNIT_IFA_AREA, a.UNIT_TYPE_CODE, a.INCL_RENT, a.RENT_SCHD_BGN_DATE)
GROUP BY EST_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE, RENT_SCHD_BGN_DATE
HAVING COUNT(*) > 1) d
WHERE a.EST_KEY = d.EST_KEY AND a.UNIT_IFA_AREA = d.UNIT_IFA_AREA
AND a.UNIT_TYPE_CODE = d.UNIT_TYPE_CODE AND a.RENT_SCHD_BGN_DATE = d.RENT_SCHD_BGN_DATE) e
WHERE a.EST_KEY = e.EST_KEY AND a.BLK_KEY = e.BLK_KEY AND a.UNIT_IFA_AREA = e.UNIT_IFA_AREA
AND a.RENT_SCHD_BGN_DATE <> e.RENT_SCHD_BGN_DATE AND a.UNIT_ENV_CODE = e.UNIT_ENV_CODE
GROUP BY a.EST_KEY, a.BLK_KEY, a.UNIT_IFA_AREA, a.UNIT_TYPE_CODE, a.UNIT_ENV_CODE) f
WHERE a.EST_KEY = f.EST_KEY AND a.BLK_KEY = f.BLK_KEY AND a.UNIT_IFA_AREA = f.UNIT_IFA_AREA
AND a.RENT_SCHD_BGN_DATE = f.RENT_SCHD_BGN_DATE AND a.UNIT_ENV_CODE = f.UNIT_ENV_CODE;

