-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HSM_UNIT
SELECT 
/*+ FULL(aply) FULL(aply_sts) FULL(tncy) FULL(tncy_sts) */
tncy_sts.TNCY_AGRMT_CMNC_DATE, prev_unit.UNIT_ADDR_CODE AS UNIT_ADDR_CODE_PREV, prev_unit.UNIT_IFA_AREA AS UNIT_IFA_AREA_PREV,
cur_unit.UNIT_ADDR_CODE AS UNIT_ADDR_CODE_CUR, cur_unit.UNIT_IFA_AREA AS UNIT_IFA_AREA_CUR, aply_sts.CUST_CSSA_IND, tncy_sts.RENT_FCTR_CODE, tncy.CUST_KEY, tncy.HSE_SRVC_APLY_KEY,
prev_blk.EMMS_BLK_KEY AS PREV_EMMS_BLK_KEY, prev_unit.UNIT_TYPE_CODE AS PREV_UNIT_TYPE_CODE, 
prev_unit_sts.HSE_UNIT_ENV_CODE AS PREV_HSE_UNIT_ENV_CODE, prev_unit.UNIT_IFA_AREA AS PREV_UNIT_IFA_AREA,
cur_blk.EMMS_BLK_KEY AS CUR_EMMS_BLK_KEY, cur_unit.UNIT_TYPE_CODE AS CUR_UNIT_TYPE_CODE, 
cur_unit_sts.HSE_UNIT_ENV_CODE AS CUR_HSE_UNIT_ENV_CODE, cur_unit.UNIT_IFA_AREA AS CUR_UNIT_IFA_AREA
FROM SOR_EMS_TAM_TNCY_CNCL cncl, SOR_EMS_TAM_TNCY_CNCL_STS cncl_sts,
SOR_EMS_TAM_TNCY_AGRMT tncy, SOR_EMS_TAM_TNCY_AGRMT_STS tncy_sts,
SOR_HSM_UNIT prev_unit, SOR_HSM_UNIT_STS prev_unit_sts,
SOR_HSM_UNIT cur_unit, SOR_HSM_UNIT_STS cur_unit_sts,
SOR_EMS_CPM_CUST_APLY aply, SOR_EMS_CPM_CUST_APLY_STS aply_sts,
SOR_HSM_BLK prev_blk, SOR_HSM_BLK cur_blk
WHERE cncl.TNCY_CNCL_KEY = cncl_sts.TNCY_CNCL_KEY
AND tncy.TNCY_AGRMT_KEY = tncy_sts.TNCY_AGRMT_KEY
AND prev_unit.UNIT_KEY = prev_unit_sts.UNIT_KEY
AND cur_unit.UNIT_KEY = cur_unit_sts.UNIT_KEY
AND aply.CUST_APLY_KEY = aply_sts.CUST_APLY_KEY
AND cncl_sts.UNIT_KEY = prev_unit.UNIT_KEY
AND tncy_sts.UNIT_KEY = cur_unit.UNIT_KEY
AND SUBSTR(cncl.TNCY_CNCL_BK,11,24) = tncy_sts.PREV_CUST_KEY || tncy_sts.PREV_HSE_SRVC_APLY_KEY
AND aply.CUST_APLY_BK = SUBSTR(tncy.TNCY_AGRMT_BK,1,9) || tncy_sts.PREV_HSE_SRVC_APLY_KEY
AND tncy_sts.TNCY_AGRMT_STS_CODE = 'A'
AND cncl_sts.TNCY_CNCL_CODE IN ('G6','F6')
AND prev_unit.BLK_KEY = prev_blk.BLK_KEY
AND cur_unit.BLK_KEY = cur_blk.BLK_KEY
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cncl_sts.BGN_DATE AND cncl_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN prev_unit_sts.BGN_DATE AND prev_unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cur_unit_sts.BGN_DATE AND cur_unit_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN tncy_sts.BGN_DATE AND tncy_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN aply_sts.BGN_DATE AND aply_sts.END_DATE;

-- [SELECT] Step: read_LKP_CUR_RENT
-- Connection: DPA
SELECT rfx.BLK_KEY as BLK_KEY, rfx_sts.UNIT_TYPE_CODE as UNIT_TYPE_CODE, rfx.UNIT_ENV_CODE as UNIT_ENV_CODE, rfx.UNIT_IFA_AREA as UNIT_IFA_AREA, rfx_sts.RENT_SCHD_BGN_DATE AS RENT_SCHD_BGN_DATE
FROM SOR_EMS_RFX_RENT_SCHD_HIST rfx, SOR_EMS_RFX_RENT_SCHD_HIST_STS rfx_sts
WHERE rfx.RENT_SCHD_AMND_HIST_KEY = rfx_sts.RENT_SCHD_AMND_HIST_KEY
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN rfx_sts.BGN_DATE AND rfx_sts.END_DATE
AND rfx.TNT_RENT_CODE_CATG_CODE = 'N'
GROUP BY rfx.BLK_KEY, rfx_sts.UNIT_TYPE_CODE, rfx.UNIT_ENV_CODE, rfx.UNIT_IFA_AREA, rfx_sts.RENT_SCHD_BGN_DATE;

-- [SELECT] Step: read_LKP_HH_SIZE
-- Connection: DPA
SELECT COUNT(1) as HH_CNT, tncy.CUST_KEY as CUST_KEY, tncy.HSE_SRVC_APLY_KEY as HSE_SRVC_APLY_KEY
FROM SOR_EMS_TAM_TNCY_CNCL cncl, SOR_EMS_TAM_TNCY_CNCL_STS cncl_sts,
SOR_EMS_TAM_TNCY_AGRMT tncy, SOR_EMS_TAM_TNCY_AGRMT_STS tncy_sts,
SOR_EMS_CPM_CUST_APLY_MBR mbr, SOR_EMS_CPM_CUST_APLY_MBR_STS mbr_sts
WHERE cncl.TNCY_CNCL_KEY = cncl_sts.TNCY_CNCL_KEY
AND tncy.TNCY_AGRMT_KEY = tncy_sts.TNCY_AGRMT_KEY
AND mbr.CUST_APLY_MBR_KEY = mbr_sts.CUST_APLY_MBR_KEY
AND SUBSTR(cncl.TNCY_CNCL_BK,11,24) = tncy_sts.PREV_CUST_KEY || tncy_sts.PREV_HSE_SRVC_APLY_KEY
AND tncy.TNCY_AGRMT_BK = SUBSTR(mbr.CUST_APLY_MBR_BK,1,9) || SUBSTR(mbr.CUST_APLY_MBR_BK,24,15)
AND tncy_sts.TNCY_AGRMT_STS_CODE = 'A'
AND cncl_sts.TNCY_CNCL_CODE IN ('G6','F6')
AND mbr_sts.CUST_APLY_MBR_STS_CODE = 'A'
AND mbr.HSE_SRVC_APLY_TYPE_CODE = 'T'
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN cncl_sts.BGN_DATE AND cncl_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN tncy_sts.BGN_DATE AND tncy_sts.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN mbr_sts.BGN_DATE AND mbr_sts.END_DATE
GROUP BY tncy.CUST_KEY, tncy.HSE_SRVC_APLY_KEY;

-- [SELECT] Step: read_LKP_PREV_RENT
-- Connection: DPA
SELECT rfx.BLK_KEY as BLK_KEY, rfx_sts.UNIT_TYPE_CODE as UNIT_TYPE_CODE, rfx.UNIT_ENV_CODE as UNIT_ENV_CODE, rfx.UNIT_IFA_AREA as UNIT_IFA_AREA, rfx_sts.RENT_SCHD_BGN_DATE AS RENT_SCHD_BGN_DATE
