-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_BRO
SELECT rgn.RGN_CODE, est.EST_CODE, est.EST_KEY, blk.BLK_CODE
FROM SOR_HSM_EST est,
SOR_HSM_EST_RGN_RLTN er, SOR_HSM_RGN rgn, 
SOR_HSM_BLK blk,SOR_HSM_BLK_STS blk_sts 
WHERE  
blk.BLK_KEY = blk_sts.BLK_KEY AND 
rgn.RGN_KEY = er.RGN_KEY AND 
est.EST_KEY = er.EST_KEY AND
est.EST_KEY = blk.EST_KEY AND
est.EST_CODE IN ('HF','YSG') AND est.EST_TYPE_CODE = 'E'
AND blk.EMMS_BLK_KEY IS NOT NULL
AND rgn.RGN_TYPE_CODE = 'RM'
AND blk_sts.HSE_BLK_TNTV_CMPLT_DATE IS NOT NULL
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN er.BGN_DATE AND er.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_IH
SELECT rgn.RGN_CODE, est.EST_CODE, est.EST_KEY, blk.BLK_CODE
FROM SOR_HSM_EST est,
SOR_HSM_EST_RGN_RLTN er, SOR_HSM_RGN rgn,
SOR_HSM_BLK blk, SOR_HSM_BLK_STS blk_sts  
WHERE  
blk.BLK_KEY = blk_sts.BLK_KEY AND
er.RGN_KEY = rgn.RGN_KEY AND
est.EST_KEY = blk.EST_KEY AND
est.EST_KEY = er.EST_KEY AND 
est.EST_CODE LIKE '9%' AND 
est.EST_TYPE_CODE = 'E'
AND blk.BLK_HOVR_DATE IS NOT NULL
AND blk.EMMS_BLK_KEY IS NOT NULL
AND rgn.RGN_TYPE_CODE = 'RM'
AND blk_sts.HSE_BLK_TNTV_CMPLT_DATE IS NOT NULL
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN er.BGN_DATE AND er.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_PRH
SELECT rgn.RGN_CODE, est.EST_CODE, est.EST_KEY, blk.BLK_CODE
FROM SOR_HSM_EST est,
SOR_HSM_EST_RGN_RLTN er, SOR_HSM_RGN rgn, 
SOR_HSM_BLK blk,SOR_HSM_BLK_STS blk_sts 
WHERE  
blk.BLK_KEY = blk_sts.BLK_KEY AND 
rgn.RGN_KEY = er.RGN_KEY AND 
est.EST_KEY = er.EST_KEY AND
est.EST_KEY = blk.EST_KEY AND
est.EST_TYPE_CODE = 'E' AND SUBSTR(est.EST_CODE,1,1) <> '9'
AND blk.BLK_HOVR_DATE IS NOT NULL
AND blk.EMMS_BLK_KEY IS NOT NULL
AND rgn.RGN_TYPE_CODE = 'RM'
AND blk_sts.HSE_BLK_TNTV_CMPLT_DATE IS NOT NULL
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN er.BGN_DATE AND er.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN blk_sts.BGN_DATE AND blk_sts.END_DATE;

